package com.alpharip.staffmod.IncidentPostMortemBoard;
import java.util.*;
public final class IncidentRecord {
 private String id,title,description,reporter,owner; private IncidentCategory category; private IncidentSeverity severity; private IncidentStatus status; private long createdAt,updatedAt,resolvedAt;
 private IncidentRootCause rootCause; private IncidentImpact impact; private List<IncidentTimelineEntry> timeline=new ArrayList<IncidentTimelineEntry>(); private List<IncidentAction> actions=new ArrayList<IncidentAction>(); private List<IncidentLesson> lessons=new ArrayList<IncidentLesson>(); private List<IncidentAssignment> assignments=new ArrayList<IncidentAssignment>();
 public IncidentRecord(){}
 public IncidentRecord(String t,String d,IncidentCategory c,IncidentSeverity s,String p,long n){id=UUID.randomUUID().toString();title=req(t);description=req(d);category=c==null?IncidentCategory.OTHER:c;severity=s==null?IncidentSeverity.MEDIUM:s;reporter=req(p);owner="";status=IncidentStatus.OPEN;if(n<=0)throw new IllegalArgumentException("Timestamp must be positive");createdAt=updatedAt=n;}
 public String getId(){return id;} public String getTitle(){return title;} public String getDescription(){return description;} public String getReporter(){return reporter;} public String getOwner(){return owner;} public IncidentCategory getCategory(){return category;} public IncidentSeverity getSeverity(){return severity;} public IncidentStatus getStatus(){return status;} public long getCreatedAt(){return createdAt;} public long getUpdatedAt(){return updatedAt;} public long getResolvedAt(){return resolvedAt;} public IncidentRootCause getRootCause(){return rootCause;} public IncidentImpact getImpact(){return impact;}
 public List<IncidentTimelineEntry> getTimeline(){return new ArrayList<IncidentTimelineEntry>(timeline);} public List<IncidentAction> getActions(){return new ArrayList<IncidentAction>(actions);} public List<IncidentLesson> getLessons(){return new ArrayList<IncidentLesson>(lessons);} public List<IncidentAssignment> getAssignments(){return new ArrayList<IncidentAssignment>(assignments);}
 public void setStatus(IncidentStatus s,long n){if(s==null)throw new IllegalArgumentException("Status required");status=s;touch(n);resolvedAt=(s==IncidentStatus.RESOLVED||s==IncidentStatus.CLOSED)?n:0L;}
 public void assign(String a,String actor,long n){owner=a==null?"":a.trim();assignments.add(new IncidentAssignment(owner,actor,n));touch(n);}
 public void addTimeline(IncidentTimelineEntry e){if(e==null)throw new IllegalArgumentException("Entry required");timeline.add(e);touch(e.getTimestamp());} public void setRootCause(IncidentRootCause r){rootCause=r;if(r!=null)touch(r.getReviewedAt());} public void setImpact(IncidentImpact i){impact=i;if(i!=null)touch(i.getAssessedAt());} public void addAction(IncidentAction a){if(a==null)throw new IllegalArgumentException("Action required");actions.add(a);touch(a.getCreatedAt());} public void addLesson(IncidentLesson l){if(l==null)throw new IllegalArgumentException("Lesson required");lessons.add(l);touch(l.getCreatedAt());}
 private void touch(long n){if(n<=0)throw new IllegalArgumentException("Timestamp must be positive");updatedAt=n;} private static String req(String s){if(s==null||s.trim().isEmpty())throw new IllegalArgumentException("Required value missing");return s.trim();}
}